package org.example.backend.service;
import org.example.backend.entity.UserEntity;
import org.example.backend.mapper.*;
import org.junit.jupiter.api.Test;
import org.springframework.context.ApplicationContext;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class AiCatalogReadersBehaviorTest {
    @Test void registeredReadersAcceptEmptySourcesWithoutTreatingThemAsFailures(){Map<Class<?>,Object> sources=new HashMap<>();ApplicationContext beans=mock(ApplicationContext.class);when(beans.getBean(any(Class.class))).thenAnswer(call->sources.computeIfAbsent(call.getArgument(0),type->mock(type,invocation->invocation.getMethod().getName().equals("getLabSoftware")?org.example.backend.result.Result.success(List.of()):RETURNS_DEFAULTS.answer(invocation))));AiBusinessDataService service=new AiBusinessDataService(beans);for(String role:List.of("systemAdmin","labAdmin")){AiDataActor actor=new AiDataActor(7,role,"管理员",Set.of());for(Map<String,String> entry:service.catalog(actor)){String id=entry.get("dataset");if(id.equals("timetable"))continue;Map<String,Object> result=service.query(actor,Map.of("dataset",id,"labId",7,"deviceId",1,"sourceType","mock","eventType","online","eventLevel","info","status","online"));if(role.equals("labAdmin")&&Set.of("runtime-status","iot-environment","teacher-host","student-clients").contains(id)){assertEquals("unavailable",result.get("status"),id);assertEquals("无权查询该实验室数据",result.get("message"));}else assertEquals("ok",result.get("status"),id+result);}}}
    @Test void runtimeReadersUnwrapSupportedCollectionsAndRetainSourceTotals(){ApplicationContext beans=mock(ApplicationContext.class);DeviceStatusService runtime=mock(DeviceStatusService.class);when(beans.getBean(DeviceStatusService.class)).thenReturn(runtime);AiBusinessDataService service=new AiBusinessDataService(beans);AiDataActor actor=new AiDataActor(7,"labAdmin","管理员",Set.of());for(String key:List.of("records","clients","list")){when(runtime.listEvents(anyMap())).thenReturn(Map.of(key,List.of(Map.of("id",1,"status","online","createdAt","2026-10-18")),"total",5));Map<String,Object> result=service.query(actor,Map.of("dataset","runtime-events","date","2026-10-18","status","online"));assertEquals("ok",result.get("status"));assertEquals(1,result.get("total"));assertEquals(5,result.get("sourceTotal"));assertEquals(false,result.get("totalIsExact"));}when(runtime.getSummary(anyMap())).thenReturn(Map.of("online",3));assertEquals(Map.of("online",3),service.query(actor,Map.of("dataset","runtime-summary")).get("data"));}
    @Test void userOptionsExposeIdentityButNeverCredentialFields(){ApplicationContext beans=mock(ApplicationContext.class);UserService users=mock(UserService.class);when(beans.getBean(UserService.class)).thenReturn(users);UserEntity user=new UserEntity();user.setId(1);user.setRealName("用户甲");user.setRoleName("实验室管理员");user.setDepartment("实验中心");user.setStatus(1);user.setPassword("secret");when(users.listUsers()).thenReturn(List.of(user));AiBusinessDataService service=new AiBusinessDataService(beans);Map<String,Object> result=service.query(new AiDataActor(7,"systemAdmin","管理员",Set.of()),Map.of("dataset","users"));assertEquals("ok",result.get("status"));assertTrue(result.toString().contains("用户甲"));assertFalse(result.toString().contains("secret"));}
    @Test void labScopedReadersRequireExplicitLabAndDenyUnknownManagerScope(){ApplicationContext beans=mock(ApplicationContext.class);IotDeviceService iot=mock(IotDeviceService.class);when(beans.getBean(IotDeviceService.class)).thenReturn(iot);when(beans.getBean(LabRecordReadService.class)).thenReturn(mock(LabRecordReadService.class));AiBusinessDataService service=new AiBusinessDataService(beans);AiDataActor actor=new AiDataActor(7,"labAdmin","管理员",Set.of());assertTrue(service.query(actor,Map.of("dataset","iot-environment")).get("message").toString().contains("labId"));assertEquals("无权查询该实验室数据",service.query(actor,Map.of("dataset","iot-environment","labId",1)).get("message"));verifyNoInteractions(iot);}
}

